#[path = "solution.rs"]
mod solution;

use solution::{FixedGrid, GridError, HeldInput};

#[test]
fn validates_parameters_in_required_order() {
    assert_eq!(FixedGrid::new(0, 0, 0), Err(GridError::ZeroStep));
    assert_eq!(FixedGrid::new(0, 0, 1), Err(GridError::ZeroWidth));
    assert_eq!(FixedGrid::new(1, 0, 1), Err(GridError::ZeroHeight));
}

#[test]
fn exact_interval_steps_and_partial_time_is_retained() {
    let mut grid = FixedGrid::new(10, 10, 10).unwrap();
    let input = HeldInput { right: true, down: true, ..HeldInput::default() };
    let before = input;
    assert_eq!(grid.advance(0, &input), 0);
    assert_eq!(grid.advance(9, &input), 0);
    assert_eq!((grid.x, grid.y), (0, 0));
    assert_eq!(grid.advance(1, &input), 1);
    assert_eq!((grid.x, grid.y), (1, 1));
    assert_eq!(grid.advance(25, &input), 2);
    assert_eq!((grid.x, grid.y), (3, 3));
    assert_eq!(grid.advance(5, &input), 1);
    assert_eq!((grid.x, grid.y), (4, 4));
    assert_eq!(input, before);
}

#[test]
fn opposing_inputs_cancel_independently() {
    let mut grid = FixedGrid::new(5, 5, 1).unwrap();
    let input = HeldInput { left: true, right: true, up: true, down: true };
    assert_eq!(grid.advance(3, &input), 3);
    assert_eq!((grid.x, grid.y), (0, 0));
}

#[test]
fn coordinates_are_clamped_at_all_edges() {
    let mut grid = FixedGrid::new(2, 2, 1).unwrap();
    assert_eq!(grid.advance(5, &HeldInput { right: true, down: true, ..HeldInput::default() }), 5);
    assert_eq!((grid.x, grid.y), (1, 1));
    assert_eq!(grid.advance(5, &HeldInput { left: true, up: true, ..HeldInput::default() }), 5);
    assert_eq!((grid.x, grid.y), (0, 0));
}

